import{_ as t,o as n,c as i,a2 as s}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Schreibweise","description":"Punkt, Klammern, Anführungszeichen — die Regeln für ApptiveScript-Ausdrücke.","frontmatter":{"title":"Schreibweise","description":"Punkt, Klammern, Anführungszeichen — die Regeln für ApptiveScript-Ausdrücke."},"headers":[],"relativePath":"apptivescript/schreibweise.md","filePath":"apptivescript/schreibweise.md","lastUpdated":1786434193000}'),a={name:"apptivescript/schreibweise.md"};function r(d,e,l,o,c,h){return n(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="schreibweise" tabindex="-1">Schreibweise <a class="header-anchor" href="#schreibweise" aria-label="Permalink to &quot;Schreibweise&quot;">​</a></h1><p>ApptiveScript kennt wenige Regeln. Diese Seite listet sie vollständig auf.</p><h2 id="wert-punkt-funktion" tabindex="-1">Wert, Punkt, Funktion <a class="header-anchor" href="#wert-punkt-funktion" aria-label="Permalink to &quot;Wert, Punkt, Funktion&quot;">​</a></h2><p>Jeder Ausdruck beginnt mit einem Wert. Dahinter folgen, jeweils mit einem Punkt getrennt, Funktionen:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fieldValue(&#39;preis&#39;).multiplyBy(1.19)</span></span></code></pre></div><p>Das Ergebnis einer Funktion ist wieder ein Wert — deshalb lassen sich Funktionen <strong>verketten</strong>. Gelesen wird von links nach rechts:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fieldValue(&#39;nachname&#39;).concat(fieldValue(&#39;vorname&#39;), &#39;, &#39;).isNotEmpty()</span></span></code></pre></div><p>Welche Funktion erlaubt ist, hängt vom Typ des Wertes links vom Punkt ab. Ein Text kann <code>contains()</code>, eine Zahl kann <code>round()</code>. → <a href="/referenz/apptivescript-funktionen">Funktionsreferenz</a></p><p>Leerzeichen und Zeilenumbrüche zwischen den Teilen sind erlaubt. Für längere Ketten ist das die lesbarere Form:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fieldValue(&#39;menge&#39;)</span></span>
<span class="line"><span>  .multiplyBy(fieldValue(&#39;einzelpreis&#39;))</span></span>
<span class="line"><span>  .round(2)</span></span></code></pre></div><h2 id="funktionen-haben-immer-klammern" tabindex="-1">Funktionen haben immer Klammern <a class="header-anchor" href="#funktionen-haben-immer-klammern" aria-label="Permalink to &quot;Funktionen haben immer Klammern&quot;">​</a></h2><p>Auch dann, wenn sie kein Argument brauchen:</p><table tabindex="0"><thead><tr><th>Richtig</th><th>Falsch</th></tr></thead><tbody><tr><td><code>today()</code></td><td><code>today</code></td></tr><tr><td><code>fieldValue(&#39;titel&#39;).isEmpty()</code></td><td><code>fieldValue(&#39;titel&#39;).isEmpty</code></td></tr></tbody></table><p>Ausnahme sind <strong>Eigenschaften</strong>. Sie stehen ohne Klammern, weil sie nichts berechnen, sondern nur einen Teil eines Wertes benennen — in der Funktionsreferenz stehen sie mit vorangestelltem Punkt:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>loggedInUser().email</span></span></code></pre></div><p><code>true</code> und <code>false</code> sind ebenfalls Eigenschaften und stehen ohne Klammern.</p><h2 id="text-zahlen-wahrheitswerte" tabindex="-1">Text, Zahlen, Wahrheitswerte <a class="header-anchor" href="#text-zahlen-wahrheitswerte" aria-label="Permalink to &quot;Text, Zahlen, Wahrheitswerte&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Art</th><th>Schreibweise</th><th>Beispiel</th></tr></thead><tbody><tr><td>Text</td><td><strong>einfache</strong> Anführungszeichen</td><td><code>&#39;Sonstiges&#39;</code></td></tr><tr><td>Ganze Zahl</td><td>ohne Trennzeichen</td><td><code>42</code>, <code>-7</code></td></tr><tr><td>Kommazahl</td><td>mit <strong>Punkt</strong> als Dezimaltrennzeichen</td><td><code>1.19</code></td></tr><tr><td>Wahrheitswert</td><td>ohne Klammern, klein geschrieben</td><td><code>true</code>, <code>false</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Drei Schreibfehler, die einen Ausdruck kippen</p><ul><li><strong>Doppelte Anführungszeichen</strong> (<code>&quot;Sonstiges&quot;</code>) sind kein gültiger Text. Der Editor meldet einen Fehler.</li><li><strong>Komma als Dezimaltrennzeichen</strong> (<code>1,19</code>) wird nicht gelesen. Immer <code>1.19</code>.</li><li><strong>Großschreibung</strong> ist verbindlich: <code>True</code> ist nicht <code>true</code>, <code>IsEmpty()</code> ist nicht <code>isEmpty()</code>. Ein falsch geschriebener Name gilt als unbekannt — und ein unbekannter Name ist kein Fehler, sondern einfach leer.</li></ul></div><div class="danger custom-block"><p class="custom-block-title">Apostrophe in Texten funktionieren nicht</p><p>Ein Apostroph innerhalb eines Textwertes lässt sich nicht schreiben — <code>&#39;Müller&#39;s Hof&#39;</code> bricht den Text nach <code>Müller</code> ab, <strong>ohne</strong> dass eine Fehlermeldung erscheint. Vermeiden Sie Apostrophe in Vergleichswerten, oder vergleichen Sie mit einem Teil des Textes über <code>contains()</code>.</p></div><h2 id="rechnen" tabindex="-1">Rechnen <a class="header-anchor" href="#rechnen" aria-label="Permalink to &quot;Rechnen&quot;">​</a></h2><p>Für Zahlen gibt es beide Schreibweisen — Rechenzeichen und Funktionen:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(fieldValue(&#39;netto&#39;) + fieldValue(&#39;versand&#39;)) * 1.19</span></span>
<span class="line"><span>fieldValue(&#39;netto&#39;).plus(fieldValue(&#39;versand&#39;)).multiplyBy(1.19)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Rechenzeichen</th><th>Funktion</th></tr></thead><tbody><tr><td><code>+</code></td><td><code>plus()</code></td></tr><tr><td><code>-</code></td><td><code>minus()</code></td></tr><tr><td><code>*</code></td><td><code>multiplyBy()</code></td></tr><tr><td><code>/</code></td><td><code>divideBy()</code></td></tr></tbody></table><p>Runde Klammern gruppieren, <code>(2 + 3) * 4</code> ergibt 20.</p><div class="tip custom-block"><p class="custom-block-title">Im Zweifel die Funktionsschreibweise</p><p>Der Editor fügt beim Zusammenklicken die Funktionen ein, nicht die Rechenzeichen — und Ketten aus Funktionen lassen sich ohne Nachdenken über Vorrangregeln erweitern. Die Rechenzeichen sind vor allem für kurze Formeln bequem.</p></div><h2 id="bedingungen-verknupfen" tabindex="-1">Bedingungen verknüpfen <a class="header-anchor" href="#bedingungen-verknupfen" aria-label="Permalink to &quot;Bedingungen verknüpfen&quot;">​</a></h2><p>Es gibt keine Schlüsselwörter für <em>und</em>, <em>oder</em>, <em>nicht</em> — es sind Funktionen auf einem Wahrheitswert:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>formValues.get(&#39;alter&#39;).greaterThan(17).logicalAnd(formValues.get(&#39;agb&#39;).isTrue())</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Gemeint</th><th>Schreibweise</th></tr></thead><tbody><tr><td>und</td><td><code>bedingung.logicalAnd(andereBedingung)</code></td></tr><tr><td>oder</td><td><code>bedingung.logicalOr(andereBedingung)</code></td></tr><tr><td>nicht</td><td><code>bedingung.isFalse()</code></td></tr><tr><td>wenn/sonst</td><td><code>bedingung.if(dann, sonst)</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">UND und ODER nicht mischen</p><p>Die Oberfläche kann einen Ausdruck nur dann als Zeilen anzeigen, wenn er durchgehend mit UND <strong>oder</strong> durchgehend mit ODER verknüpft ist. Bei einer Mischung meldet der Flow-Dialog:</p><blockquote><p><em>Dieser Ausdruck mischt UND/ODER oder lässt sich nicht in Zeilen aufteilen. Bearbeite ihn als einen Ausdruck oder nutze Zeilen mit einem gemeinsamen Operator (nur UND oder nur ODER).</em></p></blockquote><p>Der Ausdruck funktioniert weiterhin — er lässt sich nur nicht mehr über die Zeilen bearbeiten.</p></div><h2 id="fehlende-werte" tabindex="-1">Fehlende Werte <a class="header-anchor" href="#fehlende-werte" aria-label="Permalink to &quot;Fehlende Werte&quot;">​</a></h2><p>Ein leeres Feld liefert keinen Fehler, sondern einen leeren Wert. Zwei Funktionen fangen das ab:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fieldValue(&#39;spitzname&#39;).ifUndefined(&#39;unbekannt&#39;)</span></span>
<span class="line"><span>fieldValue(&#39;auftragsnummer&#39;).isNotEmpty()</span></span></code></pre></div><p><code>ifUndefined()</code> gibt es auf jedem Typ. Wichtig ist es überall dort, wo weitergerechnet wird — eine Multiplikation mit einem leeren Feld ergibt kein Ergebnis, sondern nichts.</p><h2 id="was-es-nicht-gibt" tabindex="-1">Was es nicht gibt <a class="header-anchor" href="#was-es-nicht-gibt" aria-label="Permalink to &quot;Was es nicht gibt&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Kommentare</strong></td><td><code>// …</code> und <code>/* … */</code> sind ungültig</td></tr><tr><td><strong>Variablen und Zwischenschritte</strong></td><td>ein Ausdruck ist eine Zeile</td></tr><tr><td><strong>Mehrere Ergebnisse</strong></td><td>ein Ausdruck liefert genau einen Wert</td></tr><tr><td><strong>Deutsche Funktionsnamen</strong></td><td>die Namen sind englisch, auch in der deutschen Oberfläche</td></tr></tbody></table><h2 id="fehlermeldungen-des-editors" tabindex="-1">Fehlermeldungen des Editors <a class="header-anchor" href="#fehlermeldungen-des-editors" aria-label="Permalink to &quot;Fehlermeldungen des Editors&quot;">​</a></h2><p>Der Ausdruckseditor zeigt Fehler unterhalb des Feldes an, auf Englisch und mit internen Typnamen:</p><table tabindex="0"><thead><tr><th>Meldung</th><th>Bedeutung</th></tr></thead><tbody><tr><td><em>ASString class has no function named …</em></td><td>Diese Funktion gibt es für diesen Typ nicht — prüfen Sie die <a href="/referenz/apptivescript-funktionen">Funktionsreferenz</a></td></tr><tr><td><em>function needs 1 arguments</em></td><td>Zu wenige oder zu viele Argumente in den Klammern</td></tr><tr><td><em>Unexpected token …</em></td><td>Der Ausdruck ist unvollständig, etwa eine fehlende Klammer oder ein Punkt am Ende</td></tr><tr><td><em>No field with id …</em></td><td>Die Spalte, auf die verwiesen wird, gibt es nicht mehr</td></tr></tbody></table><p>Lässt sich ein Ausdruck nicht lesen, bleibt der eingegebene Text unverändert im Feld stehen, statt in Bausteine umgewandelt zu werden. Das ist das schnellste Erkennungsmerkmal für einen Schreibfehler.</p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/apptivescript/werte-referenzieren">Werte referenzieren</a> — womit ein Ausdruck anfängt</li><li><a href="/apptivescript/bedingungen">Bedingungen bauen</a> — Vergleiche, UND/ODER, Verzweigungen</li><li><a href="/apptivescript/editor">Der Ausdruckseditor</a> — Token-Ansicht, Picker, Beispielergebnis</li><li><a href="/referenz/apptivescript-funktionen">Funktionsreferenz</a> — alle Funktionen je Typ</li><li><a href="/apptivescript/was-ist-apptivescript">Was ist ApptiveScript</a></li></ul>`,43)])])}const g=t(a,[["render",r]]);export{p as __pageData,g as default};
